const now = new Date();
const sourceUrl = $env.AIRINDEX_SOURCE_URL;
const ingestUrl = $env.AIRINDEX_INGEST_URL;
const indexUrl = $env.AIRINDEX_INDEX_URL || '';
if (!sourceUrl || !ingestUrl) throw new Error('AIRINDEX_SOURCE_URL and AIRINDEX_INGEST_URL must be configured');
return [{ json: { run_id: 'n8n-' + now.toISOString().replace(/[-:.TZ]/g, ''), collected_at: now.toISOString(), source_url: sourceUrl, ingest_url: ingestUrl, index_url: indexUrl, freshness_limit_minutes: Number($env.AIRINDEX_FRESHNESS_LIMIT_MINUTES || 180), anomaly_threshold_pct: Number($env.AIRINDEX_ANOMALY_THRESHOLD_PCT || 35), anomaly_alert_pct: Number($env.AIRINDEX_ALERT_ANOMALY_RATE_PCT || 20), batch_size: Math.max(1, Number($env.AIRINDEX_BATCH_SIZE || 100)), minimum_observations: Math.max(1, Number($env.AIRINDEX_MIN_OBSERVATIONS || 3)), minimum_routes: Math.max(1, Number($env.AIRINDEX_MIN_ROUTES || 3)), workflow_version: '0.3.0' } }];

const context = $('Run Config + Audit ID').first().json;
const first = $input.first()?.json;
let rows;
if (Array.isArray(first)) rows = first;
else if (Array.isArray(first?.observations)) rows = first.observations;
else rows = $input.all().map(item => item.json);
if (!rows.length) throw new Error('Source returned zero observations');
const valid = [];
const rejected = [];
const seen = new Set();
const now = new Date(context.collected_at);
for (const [i, row] of rows.entries()) {
  try {
    const route = String(row.route ?? '').trim().toUpperCase();
    const carrier = String(row.carrier_code ?? row.carrier ?? '').trim().toUpperCase();
    const fare = Number(row.total_fare ?? row.totalFare);
    const observed = new Date(row.observed_at ?? row.collected_at ?? context.collected_at);
    const travel = new Date(row.travel_date);
    const currency = String(row.currency ?? 'INR').toUpperCase();
    const advance = Math.round((travel - observed) / 86400000);
    if (!/^[A-Z]{3}-[A-Z]{3}$/.test(route)) throw new Error('invalid route');
    if (!/^[A-Z0-9]{2,3}$/.test(carrier)) throw new Error('invalid carrier_code');
    if (!(fare > 0) || fare > 1000000) throw new Error('invalid total_fare');
    if (currency !== 'INR') throw new Error('currency must be INR');
    if (Number.isNaN(observed.getTime()) || Number.isNaN(travel.getTime())) throw new Error('invalid date');
    if (advance < 1 || advance > 365) throw new Error('advance_days outside 1..365');
    if (travel < observed) throw new Error('travel_date before observed_at');
    const key = route + '|' + carrier + '|' + travel.toISOString().slice(0, 10) + '|' + Math.round(fare * 100);
    if (seen.has(key)) throw new Error('duplicate observation in source batch');
    seen.add(key);
    const leadWindow = [1, 7, 15, 30, 45].find(w => advance <= w) ?? 45;
    const ageMinutes = Math.max(0, (now - observed) / 60000);
    const freshness = Math.max(0, Math.min(1, 1 - ageMinutes / context.freshness_limit_minutes));
    valid.push({ route, carrier_code: carrier, observed_at: observed.toISOString(), travel_date: travel.toISOString().slice(0, 10), total_fare: Math.round(fare * 100) / 100, advance_days: advance, lead_time_window: 'T+' + leadWindow, currency, source: row.source ?? 'configured_source', run_id: context.run_id, freshness_score: Number(freshness.toFixed(4)), row_number: i + 1 });
  } catch (error) {
    rejected.push({ row_number: i + 1, reason: error.message ?? String(error) });
  }
}
if (!valid.length) throw new Error('All observations rejected: ' + JSON.stringify(rejected.slice(0, 5)));
return [{ json: { ...context, observations: valid, source_count: rows.length, rejected_count: rejected.length, rejected_examples: rejected.slice(0, 10) } }];

const data = $input.first().json;
const byRoute = new Map();
for (const obs of data.observations) {
  if (!byRoute.has(obs.route)) byRoute.set(obs.route, []);
  byRoute.get(obs.route).push(obs.total_fare);
}
const medians = {};
for (const [route, fares] of byRoute) {
  const values = [...fares].sort((a, b) => a - b);
  const mid = Math.floor(values.length / 2);
  medians[route] = values.length % 2 ? values[mid] : (values[mid - 1] + values[mid]) / 2;
}
const observations = data.observations.map(obs => {
  const median = medians[obs.route];
  const deviationPct = median > 0 ? ((obs.total_fare - median) / median) * 100 : 0;
  const anomaly = Math.abs(deviationPct) >= data.anomaly_threshold_pct;
  const score = Math.max(0, Math.min(1, 0.55 + 0.30 * obs.freshness_score + 0.15 * (anomaly ? 0.25 : 1)));
  return { ...obs, route_median_fare: Number(median.toFixed(2)), deviation_pct: Number(deviationPct.toFixed(2)), anomaly_flag: anomaly, quality_score: Number(score.toFixed(4)) };
});
const anomalyCount = observations.filter(o => o.anomaly_flag).length;
return [{ json: { ...data, observations, anomaly_count: anomalyCount, anomaly_rate_pct: Number((100 * anomalyCount / observations.length).toFixed(2)), distinct_routes: Object.keys(medians).length, quality_avg: Number((observations.reduce((s, o) => s + o.quality_score, 0) / observations.length).toFixed(4)) } }];

const data = $input.first().json;
const groups = new Map();
for (const obs of data.observations) {
  const key = obs.route + '|' + obs.lead_time_window;
  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push(obs);
}
return [...groups.entries()].map(([batchGroup, observations]) => ({ json: { ...data, batch_group: batchGroup, observations: observations.map(o => ({ ...o })), batch_source_count: observations.length } }));

const batchSize = $('Run Config + Audit ID').first().json.batch_size;
const output = [];
let sequence = 0;
for (const item of $input.all()) {
  const rows = item.json.observations ?? [];
  for (let start = 0; start < rows.length; start += batchSize) {
    sequence += 1;
    const observations = rows.slice(start, start + batchSize);
    output.push({ json: { run_id: item.json.run_id, batch_id: item.json.run_id + '-b' + sequence, batch_number: sequence, batch_group: item.json.batch_group, batch_count: observations.length, observations } });
  }
}
return output;

const base = $('Run Config + Audit ID').first().json;
const quality = $('Anomaly + Quality Scoring').first().json;
const batches = $('Controlled Batch Planner').all();
const responses = $input.all();
return [{ json: { run_id: base.run_id, workflow_version: base.workflow_version, processed_at: new Date().toISOString(), source_url: base.source_url, source_count: quality.source_count, accepted_count: quality.observations.length, rejected_count: quality.rejected_count, rejected_examples: quality.rejected_examples, distinct_routes: quality.distinct_routes, anomaly_count: quality.anomaly_count, anomaly_rate_pct: quality.anomaly_rate_pct, quality_avg: quality.quality_avg, batch_count: batches.length, dispatched_observations: batches.reduce((sum, item) => sum + Number(item.json.batch_count || 0), 0), ingest_responses: responses.map((item, index) => ({ batch_id: batches[index]?.json?.batch_id ?? null, response: item.json })) } }];

const audit = $('Build Run Audit Summary').first().json;
const indexPayload = $input.first()?.json ?? {};
return [{ json: { ...audit, latest_index: indexPayload.national_index ?? indexPayload.index ?? null, index_status: indexPayload.status ?? 'not_configured_or_unavailable', provenance: { workflow_version: audit.workflow_version, source_url: audit.source_url, generated_at: new Date().toISOString() } } }];
